#!/usr/bin/env bash
# Container entrypoint for the single-service Render deployment (Dockerfile.render).
#   1. Create the three DB roles + database (idempotent) using the Neon owner connection (ADMIN_DATABASE_URL).
#   2. Apply migrations as hms_owner.
#   3. Seed demo data when SEED_DEMO=true (idempotent; passwords from DEMO_PASSWORD_*).
#   4. Run the API on 127.0.0.1:4000 and the web server on $PORT; exit if either stops.
# No secret is printed. Role passwords come from env (generated by Render), never from the repo.
set -euo pipefail

: "${ADMIN_DATABASE_URL:?ADMIN_DATABASE_URL (Neon connection string of the owner role) is required}"
: "${DB_OWNER_PASSWORD:?}" "${DB_APP_PASSWORD:?}" "${DB_SYSTEM_PASSWORD:?}"
export DB_NAME="${DB_NAME:-hms}"
ROOT="${APP_ROOT:-/app}"
API_DIR="$ROOT/apps/api"
WEB_DIR="${WEB_DIR:-/srv/web}"
API_PORT="${API_PORT:-4000}"

# Public origin of this service (Render sets RENDER_EXTERNAL_URL, e.g. https://name.onrender.com).
export APP_ORIGINS="${APP_ORIGINS:-${RENDER_EXTERNAL_URL:-}}"
[ -n "$APP_ORIGINS" ] || { echo "APP_ORIGINS or RENDER_EXTERNAL_URL must be set" >&2; exit 1; }

# Build per-role URLs from the admin URL: same host/SSL options, different user, password and database.
role_url() { # $1 user, $2 password env var name
  node -e '
    const u = new URL(process.env.ADMIN_DATABASE_URL);
    u.username = process.argv[1];
    u.password = process.env[process.argv[2]];
    u.pathname = "/" + process.env.DB_NAME;
    u.searchParams.delete("channel_binding");            // not understood by the Prisma engine
    if (!u.searchParams.has("sslmode")) u.searchParams.set("sslmode", "require");
    if (!u.searchParams.has("connect_timeout")) u.searchParams.set("connect_timeout", "30"); // Neon cold start
    process.stdout.write(u.toString());
  ' "$1" "$2"
}
export MIGRATION_DATABASE_URL="$(role_url hms_owner DB_OWNER_PASSWORD)"
export DATABASE_URL="$(role_url hms_app DB_APP_PASSWORD)"
export DATABASE_SYSTEM_URL="$(role_url hms_system DB_SYSTEM_PASSWORD)"

echo "[start] database roles"
for i in 1 2 3 4 5; do
  if psql "$ADMIN_DATABASE_URL" -v ON_ERROR_STOP=1 -q \
      -v owner_pw="$DB_OWNER_PASSWORD" -v app_pw="$DB_APP_PASSWORD" -v system_pw="$DB_SYSTEM_PASSWORD" -v db="$DB_NAME" \
      -f "$ROOT/scripts/sql/roles.sql"; then break; fi
  [ "$i" = 5 ] && { echo "[start] could not prepare database roles" >&2; exit 1; }
  echo "[start] database not ready, retrying ($i)"; sleep 5
done

echo "[start] migrations"
cd "$API_DIR"
DATABASE_URL="$MIGRATION_DATABASE_URL" npx prisma migrate deploy

if [ "${SEED_DEMO:-false}" = "true" ]; then
  echo "[start] demo seed"
  ALLOW_DEMO_SEED=true node dist/scripts/seed-demo.js
fi

echo "[start] api + web"
PORT="$API_PORT" node dist/main.js &
API_PID=$!
for i in $(seq 1 60); do
  node -e "fetch('http://127.0.0.1:$API_PORT/api/health/live').then(r=>process.exit(r.ok?0:1)).catch(()=>process.exit(1))" && break
  kill -0 "$API_PID" 2>/dev/null || { echo "[start] API exited" >&2; exit 1; }
  sleep 1
done

cd "$WEB_DIR"
PORT="${PORT:-10000}" HOSTNAME=0.0.0.0 API_INTERNAL_URL="http://127.0.0.1:$API_PORT" node apps/web/server.js &
WEB_PID=$!

trap 'kill -TERM "$API_PID" "$WEB_PID" 2>/dev/null' TERM INT
wait -n "$API_PID" "$WEB_PID"
code=$?
kill -TERM "$API_PID" "$WEB_PID" 2>/dev/null || true
exit "$code"
